import fs from 'node:fs';import vm from 'node:vm';import crypto from 'node:crypto';
const out=process.argv[2],src=fs.readFileSync('site/notes-58c0-refactor/dist/assets/app.js','utf8');
const extract=n=>{const start=src.indexOf('function '+n+'(');const end=src.indexOf('\nfunction ',start+1);return src.slice(start,end<0?undefined:end)};
const sandbox={h:String,statusOf:()=>0,HLC:{},cmpCard:()=>'',state:{qaMode:'full'},ICON:{img:'',shuffle:''},pageHead:()=>'',callout:(a,b)=>b,pager:()=>'',qKey:(id,i)=>id+'#'+(sandbox.e?.items?.[i]?.id||i),qAnchor:(id,i)=>sandbox.e?.items?.[i]?.id||i,unitsOf:()=>({ok:0,total:1}),TREE:{design:{all:[]},bagu:{all:[]}},learnerLabel:(a,b)=>b,keyCard:()=>'',sec:(t,b)=>b,relatedLinks:()=>''};vm.createContext(sandbox);
for(const name of ['splitLead','qaCardHtml','qaListHtml','qaToolbar','renderQA','renderDoc'])vm.runInContext(extract(name),sandbox);
const results=[];
for(const name of fs.readdirSync(out).filter(n=>n.endsWith('-staged.json'))){let e=JSON.parse(fs.readFileSync(out+'/'+name,'utf8'));sandbox.e=e;let result=vm.runInContext(e.kind==='qa'?'renderQA(e)':'renderDoc(e)',sandbox);if(e.kind==='doc')result+=e.supplementHtml||'';if(result.includes('undefined'))throw Error(name+' undefined');fs.writeFileSync(out+'/'+e.id+'-rendered.html',result);results.push({entryId:e.id,bytes:Buffer.byteLength(result),questions:e.items?.length||0,qaContainers:(result.match(/class="qa s0"/g)||[]).length});}
fs.writeFileSync(out+'/compiled-renderer-check.json',JSON.stringify({appSHA256:crypto.createHash('sha256').update(src).digest('hex'),method:'Actual qAnchor/qKey semantics retained; exact compiled renderDoc/renderQA/qaCardHtml helpers evaluated in isolated Node VM; unrelated navigation/status helpers stubbed. Doc pager supplement placement inspected in compiled source. Not a browser layout test.',results},null,2));console.log(results);
